  for ref,parts in anchors.items():
   for part in parts:self.assertIn(part,cases[ref.replace(':','-')]['analysis'])
  self.assertIn('ipl kjv_jesus_matthew',cases['9-5']['analysis'])
  self.assertIn('voice hear:cv but no man see:cv',cases['9-7']['analysis'])
  self.assertIn('as kjv_body_scale:pl',cases['9-18']['analysis'])
  self.assertIn('ipl they:a send:perf',cases['10-20']['analysis'])
  self.assertIn('i myself also man be:pr',cases['10-26']['analysis'])
  self.assertIn('wesg all here before god',cases['10-33']['analysis'])
  self.assertIn('wesg witness:pl',cases['10-39']['analysis'])
  self.assertIn('in name of kjv_lord kjv_baptize:psv:inf',cases['10-48']['analysis'])
  self.assertEqual(len(set(lang.lexicon)-set(prior.lexicon)),15)
